import random, itertools, sys
from collections import defaultdict
from engines.analysis.solver import optimize
from engines.analysis.coding_basis import add_symbols
from engines.analysis.contact_policy import contact_batches

def rank_vec(vecs, dim):
    basis=[]
    for value in vecs:
        x=value
        for row in basis:
            p=row & -row
            if x&p: x^=row
        if x:
            p=x & -x
            for i in range(len(basis)):
                if basis[i]&p: basis[i]^=x
            basis.append(x)
            basis.sort(key=lambda r:r&-r)
    return len(basis)

def score_sets(packets, state):
    pr=cnt=rk=0
    for i,p in enumerate(packets):
        r=rank_vec(state[i], p['dimension'])
        rk+=r
        if r==p['dimension']:
            pr+=p['priority']; cnt+=1
    return (pr,cnt,rk)

def legal_batches(tick, contacts, last_use, cooldown, eligible):
    # last_use dict station -> (band,tick)
    active=[]
    for c in contacts:
        if not c['start']<=tick<c['end']:
            continue
        last=last_use.get(c['station'])
        if last is not None:
            if last[0]!=c['band'] and tick-last[1]<=cooldown:
                continue
        offers=[(c['id'],s['packet'],s['vector']) for s in c['symbols'] if s['packet'] in eligible]
        if offers:
            active.append((c,offers))
    yield ()
    for size in range(1,len(active)+1):
        for chosen in itertools.combinations(active,size):
            cs=[x[0] for x in chosen]
            if len({c['station'] for c in cs})!=size: continue
            if len({c['craft'] for c in cs})!=size: continue
            if len({c['group'] for c in cs})!=size: continue
            lists=[]
            for c,offers in chosen:
                opts=[]
                for k in range(1,c['rate']+1):
                    for combo in itertools.combinations_with_replacement(offers,k):
                        opts.append(combo)
                lists.append(opts)
            for prod in itertools.product(*lists):
                batch=[]
                for combo in prod:
                    batch.extend(combo)
                yield tuple(batch)

def brute(request):
    packets=request['packets']; contacts=request['contacts']
    H=max(c['end'] for c in contacts)
    pidx={p['id']:i for i,p in enumerate(packets)}
    reqs=[tuple(pidx[r] for r in p['requires']) for p in packets]
    stations=sorted({c['station'] for c in contacts})
    sidx={s:i for i,s in enumerate(stations)}
    init=tuple(frozenset() for _ in packets)
    init_lu=tuple(None for _ in stations)
    memo={}
    def full(idx,state):
        return rank_vec(state[idx],packets[idx]['dimension'])==packets[idx]['dimension']
    def dfs(tick,state,lu):
        if tick==H:
            return score_sets(packets,state)
        key=(tick,state,lu)
        if key in memo: return memo[key]
        eligible=set()
        for i,p in enumerate(packets):
            if full(i,state): continue
            if not p['release']<=tick<p['deadline']: continue
            if all(full(r,state) for r in reqs[i]): eligible.add(p['id'])
        last_use={stations[j]:lu[j] for j in range(len(stations)) if lu[j] is not None}
        best=None
        for batch in legal_batches(tick,contacts,last_use,request['switch_cooldown'],eligible):
            new=[set(s) for s in state]
            for cid,pid,vec in batch:
                new[pidx[pid]].add(vec)
            new=tuple(frozenset(s) for s in new)
            new_lu=list(lu)
            used={cid for cid,_,_ in batch}
            for c in contacts:
                if c['id'] in used:
                    new_lu[sidx[c['station']]]=(c['band'],tick)
            new_lu=tuple(new_lu)
            sc=dfs(tick+1,new,new_lu)
            if best is None or sc>best: best=sc
        memo[key]=best
        return best
    return dfs(0,init,init_lu)

def rand_request(seed):
    rng=random.Random(seed)
    np=rng.randint(1,3)
    # dimension 2 mostly, some 3
    packets=[]
    for i in range(np):
        dim=rng.choice([2,2,3])
        priority=rng.randint(1,9)
        craft=f'c{i}'
        band='x'
        release=0
        deadline=rng.randint(1,3)
        # ensure prereq only previous
        reqs=[]
        for j in range(i):
            if rng.random()<0.25:
                reqs.append(packets[j]['id'])
        packets.append({'id':f'P{i}','dimension':dim,'priority':priority,'craft':craft,'band':band,'release':release,'deadline':deadline,'requires':reqs})
    # contacts with matching craft/band
    contacts=[]
    nco=rng.randint(1,4)
    for k in range(nco):
        p=rng.choice(packets)
        start=rng.randint(0,2)
        end=min(4,start+rng.randint(1,3))
        # offer one or more nonzero vectors up to dim
        dim=p['dimension']
        vecs=rng.sample(range(1,1<<dim), rng.randint(1,min(3,(1<<dim)-1)))
        contacts.append({'id':f'C{k}','station':f's{k}','craft':p['craft'],'band':p['band'],'group':f'g{k}','start':start,'end':end,'rate':1 if rng.random()<0.7 else 2,'symbols':[{'packet':p['id'],'vector':v} for v in vecs]})
    cooldown=rng.randint(0,2)
    return {'switch_cooldown':cooldown,'packets':packets,'contacts':contacts}

from comparison import replay, check_value
for seed in range(200):
    req=rand_request(seed)
    try:
        rep=optimize(req)
        # validate replay
        rb=replay(req, rep['transmissions'])
        assert rb['score']==rep['score'], (seed, rb['score'], rep['score'])
        assert sorted(rep['packets'],key=lambda x:x['id'])==sorted(rb['packets'],key=lambda x:x['id'])
        assert {(r['tick'],r['contact']) for r in rep['contacts']}=={(r['tick'],r['contact']) for r in rb['contacts']}
        b=brute(req)
        if b!=tuple(rep['score'][k] for k in ('priority','count','rank')):
            print('MISMATCH seed',seed)
            print(req)
            print('brute',b,'ours',rep['score'])
            print(rep)
            sys.exit(1)
    except RecursionError as e:
        print('recursion seed',seed,req); raise
    except Exception as e:
        print('error seed',seed,e); print(req); raise
print('all ok')
