import random, time
from engines.analysis.solver import Optimizer, _build_subspaces

def span_contains(basis_a, basis_b):
    # true if span(basis_a) contains span(basis_b): each b reduces to 0
    def reduce(x):
        for r in basis_a:
            p=r&-r
            if x&p: x^=r
        return x
    return all(reduce(v)==0 for v in basis_b)

class Opt2(Optimizer):
    def _init_contain(self):
        self.contain_by_dim={}
        for d in self.rank_by_dim:
            bases,_,_ = _build_subspaces(d)
            n=len(bases)
            mat=[[False]*n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    mat[i][j]=span_contains(bases[i], bases[j])
            self.contain_by_dim[d]=mat
    def dominates(self, key1, key2):
        s1,lu1=key1; s2,lu2=key2
        for i,d in enumerate(self.dimensions):
            if not self.contain_by_dim[d][s1[i]][s2[i]]:
                return False
        for a,b in zip(lu1,lu2):
            if a is None: continue
            if b is None: return False
            if a[0]!=b[0]: return False
            if a[1]>b[1]: return False
        return True

def forward(o):
    o._init_contain()
    H=o.horizon
    frontiers=[{} for _ in range(H+1)]
    init_key=(o.initial_state,o.initial_lu)
    frontiers[0][init_key]=('prev',None)
    for t in range(H):
        nextf=frontiers[t+1]
        for key,entry in list(frontiers[t].items()):
            state,lu=key
            eligible=o._eligible_at(t,state)
            for ns,nlu,uc,rows in o._generate_actions(t,state,lu,eligible):
                nk=(ns,nlu)
                # check existing dominates new
                dominated=False
                for ek in nextf:
                    if o.dominates(ek,nk):
                        dominated=True; break
                if dominated: continue
                for ek in list(nextf):
                    if o.dominates(nk,ek):
                        del nextf[ek]
                nextf[nk]=(key,(uc,rows))
        print('tick',t,'frontier_in',len(frontiers[t]),'frontier_out',len(nextf))
        if not nextf:
            break
    best=None
    for key in frontiers[H]:
        sc=o.score_state(key[0])
        if best is None or sc>best: best=sc; bestkey=key
    return best, len(frontiers)

def make(seed,np):
    rng=random.Random(seed)
    packets=[]
    for i in range(np):
        packets.append({'id':f'P{i}','dimension':4,'priority':1,'craft':f'c{i}','band':'x','release':0,'deadline':6,'requires':[]})
    contacts=[]
    for k in range(np):
        p=packets[k]
        vecs=rng.sample(range(1,16),6)
        contacts.append({'id':f'C{k}','station':f's{k}','craft':p['craft'],'band':'x','group':f'g{k}','start':0,'end':6,'rate':2,'symbols':[{'packet':p['id'],'vector':v} for v in vecs]})
    return {'switch_cooldown':0,'packets':packets,'contacts':contacts}

for np in [1,2,3]:
    req=make(1,np)
    o=Opt2(req)
    t=time.time(); best,lens=forward(o); print('np',np,'time',time.time()-t,'best',best,'frontier lens',lens)
