def _packet_count_outcomes(packet, contact):
    """Best per-packet score for exactly ``k`` used ticks, without early full."""
    dimension = packet["dimension"]
    bases, rank_table, trans = _build_subspaces(dimension)
    full_state = next(i for i, r in enumerate(rank_table) if r == dimension)
    offers = tuple(sym["vector"] for sym in contact["symbols"]
                   if 1 <= sym["vector"] < (1 << dimension))

    first_tick = max(contact["start"], packet["release"])
    last_tick = min(contact["end"], packet["deadline"])
    max_k = max(0, last_tick - first_tick)

    batch_options = []
    rate = contact["rate"]
    for size in range(1, rate + 1):
        batch_options.extend(combinations_with_replacement(offers, size))

    reachable = [set() for _ in range(max_k + 1)]
    parent = [dict() for _ in range(max_k + 1)]
    reachable[0].add(0)
    for k in range(1, max_k + 1):
        for state in reachable[k - 1]:
            if state == full_state:
                continue
            for batch in batch_options:
                new_state = state

                new_state = state
                for vector in batch:
                    new_state = trans[new_state][vector]
                if new_state not in reachable[k]:
                    reachable[k].add(new_state)
                    parent[k][new_state] = (state, batch)

    outcomes = []
    best_states = []
    for k in range(max_k + 1):
        best = None
        best_state = None
        for state in reachable[k]:
            rank = rank_table[state]
            if state == full_state:
                outcome = (packet["priority"], 1, dimension)
            else:
                outcome = (0, 0, rank)
            if best is None or outcome > best:
                best = outcome
                best_state = state
        outcomes.append(best)
        best_states.append(best_state)
    return first_tick, last_tick, max_k, full_state, rank_table, outcomes, best_states, parent


def _schedule_ticks(counts, intervals, horizon):
    """Assign ``counts[i]`` distinct ticks inside interval i, or return None."""
    n = len(counts)
    order = sorted(range(n), key=lambda i: (counts[i], intervals[i][1] - intervals[i][0]))
    used = [False] * horizon
    ticks = [None] * n

    def backtrack(idx):
        if idx == n:
            return True
        packet_idx = order[idx]
        need = counts[packet_idx]
        if need == 0:
            return backtrack(idx + 1)
        start, end = intervals[packet_idx]
        available = [t for t in range(start, end) if not used[t]]
        if len(available) < need:
            return False
        for chosen in combinations(available, need):
            for t in chosen:
                used[t] = True
            ticks[packet_idx] = chosen
            if backtrack(idx + 1):
                return True
            for t in chosen:
                used[t] = False
            ticks[packet_idx] = None
        return False

    if not backtrack(0):
        return None
    return ticks


def _solve_single_machine(packets, contacts, switch_cooldown):
    """Exact solver for one-contact-per-packet single-global-resource cases."""
    del switch_cooldown  # unique stations make cooldown irrelevant
    packet_index = {p["id"]: i for i, p in enumerate(packets)}
    contact_for = [None] * len(packets)
    for contact in contacts:
        served = {packet_index[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in packet_index}
        contact_for[next(iter(served))] = contact

    horizon = max(c["end"] for c in contacts)
    intervals = []
    max_ks = []
    outcomes = []
    best_states = []
    parents = []
    rank_tables = []
    full_states = []
    for packet, contact in zip(packets, contact_for):
