            if ticks is None:
                return
            key = (0, 0, 0)
            for i, k in enumerate(counts):
                outcome = outcomes[i][k]
                key = (key[0] + outcome[0], key[1] + outcome[1],
                       key[2] + outcome[2])
            if best_key is None or key > best_key:
                best_key = key
                best_counts = tuple(counts)
                best_ticks = ticks
            return
        for k in range(max_ks[packet_idx] + 1):
            counts.append(k)
            rec(packet_idx + 1)
            counts.pop()

    rec(0)

    transmissions = []
    contacts_used = []
    packets_report = []
    score = {"priority": 0, "count": 0, "rank": 0}
    for packet_idx, packet in enumerate(packets):
        k = best_counts[packet_idx]
        contact = contact_for[packet_idx]
        final_state = best_states[packet_idx][k]
        rank = rank_tables[packet_idx][final_state]
        completion = None
