            completion = best_ticks[packet_idx][-1] + 1 if k else None
        packets_report.append({
            "id": packet["id"],
            "rank": rank,
            "completion": completion,
        })
        score["rank"] += rank
        if completion is not None:
            score["priority"] += packet["priority"]
            score["count"] += 1

        if k == 0:
            continue
        sequence = []
        state = final_state
        for used in range(k, 0, -1):
            previous, batch = parents[packet_idx][used][state]
            sequence.append(batch)
            state = previous
