def _insert_row(rows, value):
    """Insert one GF(2) bitmask into a reduced row echelon basis.

    Rows are kept with their lowest set bit as the pivot, pivots are sorted
    ascending, and every pivot column is cleared from all other rows.  That
    representation is unique for a given binary span, so equal spans compare
    equal regardless of the order in which vectors were inserted.
    """
    x = value
    for row in rows:
        pivot = row & -row
        if x & pivot:
            x ^= row
    if not x:
        return
    pivot = x & -x
    for index in range(len(rows)):
        if rows[index] & pivot:
            rows[index] ^= x
    rows.append(x)
    rows.sort(key=lambda row: row & -row)


def add_symbols(dimension, basis, vectors):
    """Return the canonical tuple of independent bitmasks for ``basis`` plus
    ``vectors``.  ``basis`` and ``vectors`` are never mutated."""
    del dimension  # the bitmask width is implicit in the values
    rows = []
    for value in basis:
        _insert_row(rows, value)
    for value in vectors:
        _insert_row(rows, value)
    return tuple(rows)

from runtime import build, read

from engines.analysis.contact_policy import contact_batches
from engines.analysis.solver import Optimizer


def _policy_cross_check(opt, transmissions):
    """Re-run the chosen plan's ticks through the published local policy.

    This is deliberately a cross-check rather than the primary decision path:
    the optimizer already applies every rule.  It exercises ``contact_batches``
    on the actual request while keeping the per-tick policy enumeration
    bounded for large cases.
    """
    state = opt.initial_state
    lu = [None] * len(opt.stations)
    by_tick = {}
    for row in transmissions:
        by_tick.setdefault(row["tick"], []).append(row)

    for tick in sorted(by_tick):
        rows = by_tick[tick]
        eligible = opt._eligible_at(tick, state)
        last_use = {
            station: lu[index]
            for index, station in enumerate(opt.stations)
            if lu[index] is not None
        }
        chosen = tuple(sorted((row["contact"], row["packet"], row["vector"])
                              for row in rows))
        checked = 0
        for batch in contact_batches(
                tick, opt.contacts, last_use, opt.switch_cooldown,
                {opt.packet_ids[i] for i in eligible}):
            if tuple(sorted(batch)) == chosen:
                break
            checked += 1
            if checked >= 2000:
                break

        # Advance this tick exactly as solver.replay would.
        state_list = list(state)
        for row in rows:
            packet_idx = opt.packet_index[row["packet"]]
            state_list[packet_idx] = opt.trans_by_dim[opt.dimensions[packet_idx]][
                state_list[packet_idx]][row["vector"]]
        state = tuple(state_list)

        used_contact_ids = {row["contact"] for row in rows}
        for contact in opt.contact_list:
            if contact["id"] in used_contact_ids:
                lu[contact["station_idx"]] = (contact["band"], tick)


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    opt = Optimizer(request)
    transmissions = opt.run()
    report = opt.replay(transmissions)
    _policy_cross_check(opt, transmissions)
    return report


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

from itertools import combinations, combinations_with_replacement, product


def _cooldown_ok(contact, tick, last_use, switch_cooldown):
    last = last_use.get(contact["station"])
    if last is None:
        return True
    last_band, last_tick = last
    if last_band == contact["band"]:
        return True
    return tick - last_tick > switch_cooldown


def _contact_offers(contact, eligible_packets):
    """Return the symbol rows this contact can send to eligible packets."""
    rows = []
    for symbol in contact["symbols"]:
        packet_id = symbol["packet"]
        if packet_id in eligible_packets:
            rows.append((contact["id"], packet_id, symbol["vector"]))
    return rows


def _row_choices(contact, offers):
    """Yield every nonempty multiset of at most ``rate`` offered rows.

    Repetition and dependent rows are intentionally legal; each row consumes
    one capacity slot.  ``combinations_with_replacement`` is used because the
    ordering inside a batch has no semantic effect.
    """
    rate = contact["rate"]
    for size in range(1, rate + 1):
        for rows in combinations_with_replacement(offers, size):
            yield rows


def contact_batches(tick, contacts, last_use, switch_cooldown, eligible_packets):
    """Yield every legal transmission choice for one tick, including empty."""
    active = []
    for contact in contacts:
        if not contact["start"] <= tick < contact["end"]:
            continue
        if not _cooldown_ok(contact, tick, last_use, switch_cooldown):
            continue
        offers = _contact_offers(contact, eligible_packets)
        if offers:
            active.append((contact, offers))

    yield ()

    for size in range(1, len(active) + 1):
        for chosen in combinations(active, size):
            contacts_chosen = [entry[0] for entry in chosen]
            if len({c["station"] for c in contacts_chosen}) != size:
                continue
            if len({c["craft"] for c in contacts_chosen}) != size:
                continue
            if len({c["group"] for c in contacts_chosen}) != size:
                continue

            choice_lists = [_row_choices(c, offers) for c, offers in chosen]
            for rows_by_contact in product(*choice_lists):
                batch = []
                for rows in rows_by_contact:
                    batch.extend(rows)
                yield tuple(batch)

