"""Exact finite-horizon optimizer for the coded downlink problem.

The state for one packet is its current GF(2) span, represented as the ID of a
canonical subspace.  Ticks are advanced one at a time; at each tick the locally
legal contact choices are enumerated and deduplicated by the resulting
(packet-spans, station-history) state so redundant transmissions do not cause an
explosion.
"""

from itertools import combinations, combinations_with_replacement

from engines.analysis.coding_basis import add_symbols


def _build_subspaces(dimension):
    nonzeros = list(range(1, 1 << dimension))
    seen = set()
    bases = []
    # Every subspace has a basis of at most ``dimension`` nonzero vectors.
    for size in range(0, dimension + 1):
        for comb in combinations(nonzeros, size):
            basis = add_symbols(dimension, (), comb)
            if basis not in seen:
                seen.add(basis)
                bases.append(basis)
    bases.sort(key=lambda b: (len(b), b))
    id_map = {basis: i for i, basis in enumerate(bases)}
    rank = [len(basis) for basis in bases]
    trans = []
    size = 1 << dimension
    for basis in bases:
        row = [0] * size
        for vector in nonzeros:
            new_basis = add_symbols(dimension, basis, (vector,))
            row[vector] = id_map[new_basis]
        trans.append(tuple(row))
    return tuple(bases), rank, trans


class Optimizer:
    def __init__(self, request):
        self.switch_cooldown = request["switch_cooldown"]
        self.packets = request["packets"]
        self.contacts = request["contacts"]

        self.packet_ids = [p["id"] for p in self.packets]
        self.packet_index = {p["id"]: i for i, p in enumerate(self.packets)}
        self.dimensions = [p["dimension"] for p in self.packets]
        self.priorities = [p["priority"] for p in self.packets]
        self.releases = [p["release"] for p in self.packets]
        self.deadlines = [p["deadline"] for p in self.packets]
        self.requires = [
            tuple(self.packet_index[r] for r in p["requires"])
            for p in self.packets
        ]

        # Per-dimension subspace tables.
        self.rank_by_dim = {}
        self.trans_by_dim = {}
        for dimension in sorted({d for d in self.dimensions}):
            _, ranks, trans = _build_subspaces(dimension)
            self.rank_by_dim[dimension] = ranks
            self.trans_by_dim[dimension] = trans

        self.full_state = {
            dimension: next(
                i for i, r in enumerate(self.rank_by_dim[dimension]) if r == dimension
            )
            for dimension in self.rank_by_dim
        }

        # Normalise contact fields for fast lookups.
        self.stations = sorted({c["station"] for c in self.contacts})
        self.station_index = {s: i for i, s in enumerate(self.stations)}
        self.contact_list = []
        for raw in self.contacts:
            c = dict(raw)
            c["station_idx"] = self.station_index[c["station"]]
            c["symbols"] = self._valid_symbols(c)
            self.contact_list.append(c)

        self.horizon = max(c["end"] for c in self.contact_list)
        self.initial_state = tuple(0 for _ in self.packets)
        self.initial_lu = tuple(None for _ in self.stations)

        self.memo = {}
        self.action_memo = {}

    # ------------------------------------------------------------------
    def _valid_symbols(self, contact):
        rows = []
        for symbol in contact["symbols"]:
            packet_idx = self.packet_index.get(symbol["packet"])
            if packet_idx is None:
                continue
            packet = self.packets[packet_idx]
            vector = symbol["vector"]
            if (packet["craft"], packet["band"]) != (contact["craft"], contact["band"]):
                continue
            if vector < 1 or vector >= (1 << packet["dimension"]):
                continue
            rows.append((packet_idx, vector))
        return tuple(rows)

    def _is_full(self, packet_idx, state):
        return state[packet_idx] == self.full_state[self.dimensions[packet_idx]]

    def _rank(self, packet_idx, state):
        dim = self.dimensions[packet_idx]
        return self.rank_by_dim[dim][state[packet_idx]]

    def score_state(self, state):
        priority = 0
        count = 0
        rank = 0
        for i, _ in enumerate(self.packets):
            r = self._rank(i, state)
            rank += r
            if self._is_full(i, state):
                priority += self.priorities[i]
                count += 1
        return (priority, count, rank)

    def _cooldown_ok(self, contact, tick, lu):
        last = lu[contact["station_idx"]]
        if last is None:
            return True
        last_band, last_tick = last
        if last_band == contact["band"]:
            return True
        return tick - last_tick > self.switch_cooldown

    def _eligible_at(self, tick, state):
        eligible = set()
        for i, packet in enumerate(self.packets):
            if self._is_full(i, state):
                continue
            if not packet["release"] <= tick < packet["deadline"]:
                continue
            if all(self._is_full(r, state) for r in self.requires[i]):
                eligible.add(i)
        return eligible

    def _contact_choices(self, contact, tick, state, eligible):
        """Return distinct resulting-state choices for one active contact."""
        offers = [row for row in contact["symbols"] if row[0] in eligible]
        if not offers:
            return []
        choices = {}
        trans = [self.trans_by_dim[d] for d in self.dimensions]
        rate = contact["rate"]
        for size in range(1, rate + 1):
            for combo in combinations_with_replacement(offers, size):
                new_state = list(state)
                for packet_idx, vector in combo:
                    new_state[packet_idx] = trans[packet_idx][new_state[packet_idx]][vector]
                touched = sorted({packet_idx for packet_idx, _ in combo})
                updates = tuple((packet_idx, new_state[packet_idx])
                               for packet_idx in touched)
                if updates not in choices:
                    choices[updates] = combo
        return [(updates, combo) for updates, combo in choices.items()]

    def _generate_actions(self, tick, state, lu, eligible):
        """Yield (next_state, next_lu, used_contact_indices, row_specs)."""
        active = []
        for contact_idx, contact in enumerate(self.contact_list):
            if not contact["start"] <= tick < contact["end"]:
                continue
            if not self._cooldown_ok(contact, tick, lu):
                continue
            choices = self._contact_choices(contact, tick, state, eligible)
            if choices:
                active.append((contact_idx, contact, choices))

        if not active:
            yield state, lu, (), ()
            return

        dedup = {}

        def rec(i, cur_state, cur_lu, used_stations, used_crafts, used_groups,
                used_contacts, rows):
            if i == len(active):
                sig = (cur_state, cur_lu)
                if sig not in dedup:
                    dedup[sig] = (used_contacts, rows)
                return

            contact_idx, contact, choices = active[i]
            # Skip this contact.
            rec(i + 1, cur_state, cur_lu, used_stations, used_crafts,
                used_groups, used_contacts, rows)

            # Use this contact, if the resource classes are still free.
            if (contact["station"] in used_stations
                    or contact["craft"] in used_crafts
                    or contact["group"] in used_groups):
                return

            next_used_stations = used_stations | {contact["station"]}
            next_used_crafts = used_crafts | {contact["craft"]}
            next_used_groups = used_groups | {contact["group"]}
            next_lu_list = list(cur_lu)
            next_lu_list[contact["station_idx"]] = (contact["band"], tick)
            next_lu = tuple(next_lu_list)
            next_contacts = used_contacts + (contact_idx,)

            for updates, combo in choices:
                contact_rows = tuple(
                    (contact_idx, packet_idx, vector) for packet_idx, vector in combo
                )
                next_state_list = list(cur_state)
                for packet_idx, value in updates:
                    next_state_list[packet_idx] = value
                next_state = tuple(next_state_list)
                rec(i + 1, next_state, next_lu, next_used_stations, next_used_crafts,
                    next_used_groups, next_contacts, rows + contact_rows)

        rec(0, state, lu, set(), set(), set(), (), ())
        for sig, (used_contacts, rows) in dedup.items():
            yield sig[0], sig[1], used_contacts, rows

    def solve(self, tick, state, lu):
        if tick == self.horizon:
            return self.score_state(state)

        key = (tick, state, lu)
        if key in self.memo:
            return self.memo[key]

        eligible = self._eligible_at(tick, state)
        best_score = None
        best_action = None

        for next_state, next_lu, used_contacts, rows in self._generate_actions(
                tick, state, lu, eligible):
            score = self.solve(tick + 1, next_state, next_lu)
            if best_score is None or score > best_score:
                best_score = score
                best_action = (used_contacts, rows, next_state, next_lu)

        self.memo[key] = best_score
        self.action_memo[key] = best_action
        return best_score

    def run(self):
        self.solve(0, self.initial_state, self.initial_lu)
        transmissions = []
        tick = 0
        state = self.initial_state
        lu = self.initial_lu
        while tick < self.horizon:
            key = (tick, state, lu)
            action = self.action_memo[key]
            used_contacts, rows, next_state, next_lu = action
            for contact_idx, packet_idx, vector in rows:
                transmissions.append({
                    "tick": tick,
                    "contact": self.contact_list[contact_idx]["id"],
                    "packet": self.packet_ids[packet_idx],
                    "vector": vector,
                })
            tick += 1
            state = next_state
            lu = next_lu
        return transmissions

    def replay(self, transmissions):
        """Independently replay a plan and return the report values."""
        state = self.initial_state
        completion = [None] * len(self.packets)
        lu = [None] * len(self.stations)
        by_tick = {}
        for row in transmissions:
            by_tick.setdefault(row["tick"], []).append(row)

        for tick in sorted(by_tick):
            rows = by_tick[tick]
            used_contacts = []
            for idx in sorted({row["contact"] for row in rows}):
                used_contacts.append(next(c for c in self.contact_list if c["id"] == idx))
            for field in ("station", "craft", "group"):
                if len({c[field] for c in used_contacts}) != len(used_contacts):
                    raise ValueError("resource conflict")
            capacity = {}
            for row in rows:
                capacity[row["contact"]] = capacity.get(row["contact"], 0) + 1
            contact_by_id = {c["id"]: c for c in self.contact_list}
            for cid, used in capacity.items():
                if used > contact_by_id[cid]["rate"]:
                    raise ValueError("rate exceeded")
            # Collect vectors first, then update spans after eligibility checks.
            updates = []
            for row in rows:
                contact = contact_by_id[row["contact"]]
                if not contact["start"] <= tick < contact["end"]:
                    raise ValueError("inactive contact")
                if not self._cooldown_ok(contact, tick, tuple(lu)):
                    raise ValueError("cooldown")
                packet_idx = self.packet_index[row["packet"]]
                if (self.packets[packet_idx]["craft"], self.packets[packet_idx]["band"]) != (
                        contact["craft"], contact["band"]):
                    raise ValueError("craft/band mismatch")
                if (packet_idx, row["vector"]) not in contact["symbols"]:
                    raise ValueError("symbol not offered")
                if self._is_full(packet_idx, state):
                    raise ValueError("already decoded")
                if not self.packets[packet_idx]["release"] <= tick < self.packets[packet_idx]["deadline"]:
                    raise ValueError("outside release/deadline")
                if any(not self._is_full(r, state) for r in self.requires[packet_idx]):
                    raise ValueError("prerequisite not decoded")
                updates.append((packet_idx, row["vector"]))
            for packet_idx, vector in updates:
                trans = self.trans_by_dim[self.dimensions[packet_idx]]
                state_list = list(state)
                state_list[packet_idx] = trans[state_list[packet_idx]][vector]
                state = tuple(state_list)
            for packet_idx in range(len(self.packets)):
                if completion[packet_idx] is None and self._is_full(packet_idx, state):
                    completion[packet_idx] = tick + 1
            for c in used_contacts:
                lu[c["station_idx"]] = (c["band"], tick)

        packets_report = []
        for i, packet in enumerate(self.packets):
            packets_report.append({
                "id": packet["id"],
                "rank": self._rank(i, state),
                "completion": completion[i],
            })
        contacts_used = []
        for tick in sorted(by_tick):
            for contact_id in sorted({row["contact"] for row in by_tick[tick]}):
                contacts_used.append({"tick": tick, "contact": contact_id})
        score = self.score_state(state)
        return {
            "score": {
                "priority": score[0],
                "count": score[1],
                "rank": score[2],
            },
            "packets": packets_report,
            "contacts": contacts_used,
            "transmissions": transmissions,
        }


class _UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra != rb:
            self.parent[rb] = ra


def _split_components(request):
    """Split packets into independent groups.

    Groups are coupled through prerequisites, contacts that serve several
    packets, or contacts that share a station/craft/group while their active
    intervals overlap.  Independent groups are solved separately and their
    additive scores are summed.
    """
    packets = request["packets"]
    contacts = request["contacts"]
    pidx = {p["id"]: i for i, p in enumerate(packets)}
    uf = _UnionFind(len(packets))

    for i, packet in enumerate(packets):
        for req in packet["requires"]:
            uf.union(i, pidx[req])

    for contact in contacts:
        served = [pidx[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in pidx]
        for i in served[1:]:
            uf.union(served[0], i)

    for i, c1 in enumerate(contacts):
        served1 = {pidx[sym["packet"]] for sym in c1["symbols"] if sym["packet"] in pidx}
        if not served1:
            continue
        for c2 in contacts[:i]:
            served2 = {pidx[sym["packet"]] for sym in c2["symbols"] if sym["packet"] in pidx}
            if not served2:
                continue
            overlap = c1["start"] < c2["end"] and c2["start"] < c1["end"]
            if c1["station"] == c2["station"]:
                connected = True
            elif c1["craft"] == c2["craft"] and overlap:
                connected = True
            elif c1["group"] == c2["group"] and overlap:
                connected = True
            else:
                connected = False
            if connected:
                uf.union(next(iter(served1)), next(iter(served2)))

    groups = {}
    for i in range(len(packets)):
        groups.setdefault(uf.find(i), []).append(i)
    return [sorted(indices) for indices in groups.values()]


def _component_is_single_machine(packets, contacts):
    """Return true for one-contact-per-packet, one-global-resource cases.

    When every contact shares one craft and every station is unique, all used
    contacts conflict at every tick but there is no station cooldown coupling.
    The component can then be solved by allocating whole ticks to packets.
    """
    if len(packets) < 2:
        return False
    if any(p["requires"] for p in packets):
        return False
    if len({c["craft"] for c in contacts}) != 1:
        return False
    if len({c["station"] for c in contacts}) != len(contacts):
        return False

    packet_index = {p["id"]: i for i, p in enumerate(packets)}
    owner = [None] * len(packets)
    for contact in contacts:
        served = {packet_index[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in packet_index}
        if len(served) != 1:
            return False
        packet_idx = next(iter(served))
        if owner[packet_idx] is not None:
            return False
        owner[packet_idx] = contact
    return all(item is not None for item in owner)


def _packet_count_outcomes(packet, contact):
    """Best per-packet score for exactly ``k`` used ticks, without early full."""
    dimension = packet["dimension"]
    bases, rank_table, trans = _build_subspaces(dimension)
    full_state = next(i for i, r in enumerate(rank_table) if r == dimension)
    offers = tuple(sym["vector"] for sym in contact["symbols"]
                   if 1 <= sym["vector"] < (1 << dimension))

    first_tick = max(contact["start"], packet["release"])
    last_tick = min(contact["end"], packet["deadline"])
    max_k = max(0, last_tick - first_tick)

    batch_options = []
    rate = contact["rate"]
    for size in range(1, rate + 1):
        batch_options.extend(combinations_with_replacement(offers, size))

    reachable = [set() for _ in range(max_k + 1)]
    parent = [dict() for _ in range(max_k + 1)]
    reachable[0].add(0)
    for k in range(1, max_k + 1):
        for state in reachable[k - 1]:
            if state == full_state:
                continue
            for batch in batch_options:
                new_state = state
                for vector in batch:
                    new_state = trans[new_state][vector]
                if new_state not in reachable[k]:
                    reachable[k].add(new_state)
                    parent[k][new_state] = (state, batch)

    outcomes = []
    best_states = []
    for k in range(max_k + 1):
        best = None
        best_state = None
        for state in reachable[k]:
            rank = rank_table[state]
            if state == full_state:
                outcome = (packet["priority"], 1, dimension)
            else:
                outcome = (0, 0, rank)
            if best is None or outcome > best:
                best = outcome
                best_state = state
        outcomes.append(best)
        best_states.append(best_state)
    return first_tick, last_tick, max_k, full_state, rank_table, outcomes, best_states, parent


def _schedule_ticks(counts, intervals, horizon):
    """Assign ``counts[i]`` distinct ticks inside interval i, or return None."""
    n = len(counts)
    order = sorted(range(n), key=lambda i: (counts[i], intervals[i][1] - intervals[i][0]))
    used = [False] * horizon
    ticks = [None] * n

    def backtrack(idx):
        if idx == n:
            return True
        packet_idx = order[idx]
        need = counts[packet_idx]
        if need == 0:
            return backtrack(idx + 1)
        start, end = intervals[packet_idx]
        available = [t for t in range(start, end) if not used[t]]
        if len(available) < need:
            return False
        for chosen in combinations(available, need):
            for t in chosen:
                used[t] = True
            ticks[packet_idx] = chosen
            if backtrack(idx + 1):
                return True
            for t in chosen:
                used[t] = False
            ticks[packet_idx] = None
        return False

    if not backtrack(0):
        return None
    return ticks


def _solve_single_machine(packets, contacts, switch_cooldown):
    """Exact solver for one-contact-per-packet single-global-resource cases."""
    del switch_cooldown  # unique stations make cooldown irrelevant
    packet_index = {p["id"]: i for i, p in enumerate(packets)}
    contact_for = [None] * len(packets)
    for contact in contacts:
        served = {packet_index[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in packet_index}
        contact_for[next(iter(served))] = contact

    horizon = max(c["end"] for c in contacts)
    intervals = []
    max_ks = []
    outcomes = []
    best_states = []
    parents = []
    rank_tables = []
    full_states = []
    for packet, contact in zip(packets, contact_for):
        first, last, max_k, full_state, rank_table, out, best_state, parent =             _packet_count_outcomes(packet, contact)
        intervals.append((first, last))
        max_ks.append(max_k)
        outcomes.append(out)
        best_states.append(best_state)
        parents.append(parent)
        rank_tables.append(rank_table)
        full_states.append(full_state)

    best_key = None
    best_counts = None
    best_ticks = None
    counts = []

    def rec(packet_idx):
        nonlocal best_key, best_counts, best_ticks
        if packet_idx == len(packets):
            ticks = _schedule_ticks(tuple(counts), intervals, horizon)
            if ticks is None:
                return
            key = (0, 0, 0)
            for i, k in enumerate(counts):
                outcome = outcomes[i][k]
                key = (key[0] + outcome[0], key[1] + outcome[1],
                       key[2] + outcome[2])
            if best_key is None or key > best_key:
                best_key = key
                best_counts = tuple(counts)
                best_ticks = ticks
            return
        for k in range(max_ks[packet_idx] + 1):
            counts.append(k)
            rec(packet_idx + 1)
            counts.pop()

    rec(0)

    transmissions = []
    contacts_used = []
    packets_report = []
    score = {"priority": 0, "count": 0, "rank": 0}
    for packet_idx, packet in enumerate(packets):
        k = best_counts[packet_idx]
        contact = contact_for[packet_idx]
        final_state = best_states[packet_idx][k]
        rank = rank_tables[packet_idx][final_state]
        completion = None
        if final_state == full_states[packet_idx]:
            completion = best_ticks[packet_idx][-1] + 1 if k else None
        packets_report.append({
            "id": packet["id"],
            "rank": rank,
            "completion": completion,
        })
        score["rank"] += rank
        if completion is not None:
            score["priority"] += packet["priority"]
            score["count"] += 1

        if k == 0:
            continue
        sequence = []
        state = final_state
        for used in range(k, 0, -1):
            previous, batch = parents[packet_idx][used][state]
            sequence.append(batch)
            state = previous
        sequence.reverse()
        for tick, batch in zip(best_ticks[packet_idx], sequence):
            for vector in batch:
                transmissions.append({
                    "tick": tick,
                    "contact": contact["id"],
                    "packet": packet["id"],
                    "vector": vector,
                })
            contacts_used.append({"tick": tick, "contact": contact["id"]})

    contacts_used.sort(key=lambda row: (row["tick"], row["contact"]))
    transmissions.sort(key=lambda row: (row["tick"], row["contact"], row["packet"], row["vector"]))
    return {
        "score": score,
        "packets": packets_report,
        "contacts": contacts_used,
        "transmissions": transmissions,
    }


def _optimize_component(request, indices):
    packets = [request["packets"][i] for i in indices]
    packet_ids = {p["id"] for p in packets}
    contacts = []
    for contact in request["contacts"]:
        symbols = [sym for sym in contact["symbols"] if sym["packet"] in packet_ids]
        if symbols:
            contacts.append(dict(contact, symbols=symbols))
    if not contacts:
        packets_report = [{"id": p["id"], "rank": 0, "completion": None}
                          for p in packets]
        return {
            "score": {"priority": 0, "count": 0, "rank": 0},
            "packets": packets_report,
            "contacts": [],
            "transmissions": [],
        }
    if _component_is_single_machine(packets, contacts):
        return _solve_single_machine(packets, contacts, request["switch_cooldown"])
    subrequest = {
        "switch_cooldown": request["switch_cooldown"],
        "packets": packets,
        "contacts": contacts,
    }
    opt = Optimizer(subrequest)
    transmissions = opt.run()
    return opt.replay(transmissions)


def optimize(request):
    """Return a full report for ``request``."""
    components = _split_components(request)
    if len(components) == 1:
        return _optimize_component(request, components[0])

    reports = [_optimize_component(request, indices) for indices in components]
    score = {"priority": 0, "count": 0, "rank": 0}
    packets = []
    contacts = []
    transmissions = []
    for report in reports:
        for key in score:
            score[key] += report["score"][key]
        packets.extend(report["packets"])
        contacts.extend(report["contacts"])
        transmissions.extend(report["transmissions"])
    packet_order = {p["id"]: i for i, p in enumerate(request["packets"])}
    packets.sort(key=lambda row: packet_order[row["id"]])
    return {
        "score": score,
        "packets": packets,
        "contacts": contacts,
        "transmissions": transmissions,
    }

"""Exact finite-horizon optimizer for the coded downlink problem.

The state for one packet is its current GF(2) span, represented as the ID of a
canonical subspace.  Ticks are advanced one at a time; at each tick the locally
legal contact choices are enumerated and deduplicated by the resulting
(packet-spans, station-history) state so redundant transmissions do not cause an
explosion.
"""

from itertools import combinations, combinations_with_replacement

from engines.analysis.coding_basis import add_symbols


def _build_subspaces(dimension):
    nonzeros = list(range(1, 1 << dimension))
    seen = set()
    bases = []
    # Every subspace has a basis of at most ``dimension`` nonzero vectors.
    for size in range(0, dimension + 1):
        for comb in combinations(nonzeros, size):
            basis = add_symbols(dimension, (), comb)
            if basis not in seen:
                seen.add(basis)
                bases.append(basis)
    bases.sort(key=lambda b: (len(b), b))
    id_map = {basis: i for i, basis in enumerate(bases)}
    rank = [len(basis) for basis in bases]
    trans = []
    size = 1 << dimension
    for basis in bases:
        row = [0] * size
        for vector in nonzeros:
            new_basis = add_symbols(dimension, basis, (vector,))
            row[vector] = id_map[new_basis]
        trans.append(tuple(row))
    return tuple(bases), rank, trans


class Optimizer:
    def __init__(self, request):
        self.switch_cooldown = request["switch_cooldown"]
        self.packets = request["packets"]
        self.contacts = request["contacts"]

        self.packet_ids = [p["id"] for p in self.packets]
        self.packet_index = {p["id"]: i for i, p in enumerate(self.packets)}
        self.dimensions = [p["dimension"] for p in self.packets]
        self.priorities = [p["priority"] for p in self.packets]
        self.releases = [p["release"] for p in self.packets]
        self.deadlines = [p["deadline"] for p in self.packets]
        self.requires = [
            tuple(self.packet_index[r] for r in p["requires"])
            for p in self.packets
        ]

        # Per-dimension subspace tables.
        self.rank_by_dim = {}
        self.trans_by_dim = {}
        for dimension in sorted({d for d in self.dimensions}):
            _, ranks, trans = _build_subspaces(dimension)
            self.rank_by_dim[dimension] = ranks
            self.trans_by_dim[dimension] = trans

        self.full_state = {
            dimension: next(
                i for i, r in enumerate(self.rank_by_dim[dimension]) if r == dimension
            )
            for dimension in self.rank_by_dim
        }

        # Normalise contact fields for fast lookups.
        self.stations = sorted({c["station"] for c in self.contacts})
        self.station_index = {s: i for i, s in enumerate(self.stations)}
        self.contact_list = []
        for raw in self.contacts:
            c = dict(raw)
            c["station_idx"] = self.station_index[c["station"]]
            c["symbols"] = self._valid_symbols(c)
            self.contact_list.append(c)

        self.horizon = max(c["end"] for c in self.contact_list)
        self.initial_state = tuple(0 for _ in self.packets)
        self.initial_lu = tuple(None for _ in self.stations)

        self.memo = {}
        self.action_memo = {}

    # ------------------------------------------------------------------
    def _valid_symbols(self, contact):
        rows = []
        for symbol in contact["symbols"]:
            packet_idx = self.packet_index.get(symbol["packet"])
            if packet_idx is None:
                continue
            packet = self.packets[packet_idx]
            vector = symbol["vector"]
            if (packet["craft"], packet["band"]) != (contact["craft"], contact["band"]):
                continue
            if vector < 1 or vector >= (1 << packet["dimension"]):
                continue
            rows.append((packet_idx, vector))
        return tuple(rows)

    def _is_full(self, packet_idx, state):
        return state[packet_idx] == self.full_state[self.dimensions[packet_idx]]

    def _rank(self, packet_idx, state):
        dim = self.dimensions[packet_idx]
        return self.rank_by_dim[dim][state[packet_idx]]

    def score_state(self, state):
        priority = 0
        count = 0
        rank = 0
        for i, _ in enumerate(self.packets):
            r = self._rank(i, state)
            rank += r
            if self._is_full(i, state):
                priority += self.priorities[i]
                count += 1
        return (priority, count, rank)

    def _cooldown_ok(self, contact, tick, lu):
        last = lu[contact["station_idx"]]
        if last is None:
            return True
        last_band, last_tick = last
        if last_band == contact["band"]:
            return True
        return tick - last_tick > self.switch_cooldown

    def _eligible_at(self, tick, state):
        eligible = set()
        for i, packet in enumerate(self.packets):
            if self._is_full(i, state):
                continue
            if not packet["release"] <= tick < packet["deadline"]:
                continue
            if all(self._is_full(r, state) for r in self.requires[i]):
                eligible.add(i)
        return eligible

    def _contact_choices(self, contact, tick, state, eligible):
        """Return distinct resulting-state choices for one active contact."""
        offers = [row for row in contact["symbols"] if row[0] in eligible]
        if not offers:
            return []
        choices = {}
        trans = [self.trans_by_dim[d] for d in self.dimensions]
        rate = contact["rate"]
        for size in range(1, rate + 1):
            for combo in combinations_with_replacement(offers, size):
                new_state = list(state)
                for packet_idx, vector in combo:
                    new_state[packet_idx] = trans[packet_idx][new_state[packet_idx]][vector]
                touched = sorted({packet_idx for packet_idx, _ in combo})
                updates = tuple((packet_idx, new_state[packet_idx])
                               for packet_idx in touched)
                if updates not in choices:
                    choices[updates] = combo
        return [(updates, combo) for updates, combo in choices.items()]

    def _generate_actions(self, tick, state, lu, eligible):
        """Yield (next_state, next_lu, used_contact_indices, row_specs)."""
        active = []
        for contact_idx, contact in enumerate(self.contact_list):
            if not contact["start"] <= tick < contact["end"]:
                continue
            if not self._cooldown_ok(contact, tick, lu):
                continue
            choices = self._contact_choices(contact, tick, state, eligible)
            if choices:
                active.append((contact_idx, contact, choices))

        if not active:
            yield state, lu, (), ()
            return

        dedup = {}

        def rec(i, cur_state, cur_lu, used_stations, used_crafts, used_groups,
                used_contacts, rows):
            if i == len(active):
                sig = (cur_state, cur_lu)
                if sig not in dedup:
                    dedup[sig] = (used_contacts, rows)
                return

            contact_idx, contact, choices = active[i]
            # Skip this contact.
            rec(i + 1, cur_state, cur_lu, used_stations, used_crafts,
                used_groups, used_contacts, rows)

            # Use this contact, if the resource classes are still free.
            if (contact["station"] in used_stations
                    or contact["craft"] in used_crafts
                    or contact["group"] in used_groups):
                return

            next_used_stations = used_stations | {contact["station"]}
            next_used_crafts = used_crafts | {contact["craft"]}
            next_used_groups = used_groups | {contact["group"]}
            next_lu_list = list(cur_lu)
            next_lu_list[contact["station_idx"]] = (contact["band"], tick)
            next_lu = tuple(next_lu_list)
            next_contacts = used_contacts + (contact_idx,)

            for updates, combo in choices:
                contact_rows = tuple(
                    (contact_idx, packet_idx, vector) for packet_idx, vector in combo
                )
                next_state_list = list(cur_state)
                for packet_idx, value in updates:
                    next_state_list[packet_idx] = value
                next_state = tuple(next_state_list)
                rec(i + 1, next_state, next_lu, next_used_stations, next_used_crafts,
                    next_used_groups, next_contacts, rows + contact_rows)

        rec(0, state, lu, set(), set(), set(), (), ())
        for sig, (used_contacts, rows) in dedup.items():
            yield sig[0], sig[1], used_contacts, rows

    def solve(self, tick, state, lu):
        if tick == self.horizon:
            return self.score_state(state)

        key = (tick, state, lu)
        if key in self.memo:
            return self.memo[key]

        eligible = self._eligible_at(tick, state)
        best_score = None
        best_action = None

        for next_state, next_lu, used_contacts, rows in self._generate_actions(
                tick, state, lu, eligible):
            score = self.solve(tick + 1, next_state, next_lu)
            if best_score is None or score > best_score:
                best_score = score
                best_action = (used_contacts, rows, next_state, next_lu)

        self.memo[key] = best_score
        self.action_memo[key] = best_action
        return best_score

    def run(self):
        self.solve(0, self.initial_state, self.initial_lu)
        transmissions = []
        tick = 0
        state = self.initial_state
        lu = self.initial_lu
        while tick < self.horizon:
            key = (tick, state, lu)
            action = self.action_memo[key]
            used_contacts, rows, next_state, next_lu = action
            for contact_idx, packet_idx, vector in rows:
                transmissions.append({
                    "tick": tick,
                    "contact": self.contact_list[contact_idx]["id"],
                    "packet": self.packet_ids[packet_idx],
                    "vector": vector,
                })
            tick += 1
            state = next_state
            lu = next_lu
        return transmissions

    def replay(self, transmissions):
        """Independently replay a plan and return the report values."""
        state = self.initial_state
        completion = [None] * len(self.packets)
        lu = [None] * len(self.stations)
        by_tick = {}
        for row in transmissions:
            by_tick.setdefault(row["tick"], []).append(row)

        for tick in sorted(by_tick):
            rows = by_tick[tick]
            used_contacts = []
            for idx in sorted({row["contact"] for row in rows}):
                used_contacts.append(next(c for c in self.contact_list if c["id"] == idx))
            for field in ("station", "craft", "group"):
                if len({c[field] for c in used_contacts}) != len(used_contacts):
                    raise ValueError("resource conflict")
            capacity = {}
            for row in rows:
                capacity[row["contact"]] = capacity.get(row["contact"], 0) + 1
            contact_by_id = {c["id"]: c for c in self.contact_list}
            for cid, used in capacity.items():
                if used > contact_by_id[cid]["rate"]:
                    raise ValueError("rate exceeded")
            # Collect vectors first, then update spans after eligibility checks.
            updates = []
            for row in rows:
                contact = contact_by_id[row["contact"]]
                if not contact["start"] <= tick < contact["end"]:
                    raise ValueError("inactive contact")
                if not self._cooldown_ok(contact, tick, tuple(lu)):
                    raise ValueError("cooldown")
                packet_idx = self.packet_index[row["packet"]]
                if (self.packets[packet_idx]["craft"], self.packets[packet_idx]["band"]) != (
                        contact["craft"], contact["band"]):
                    raise ValueError("craft/band mismatch")
                if (packet_idx, row["vector"]) not in contact["symbols"]:
                    raise ValueError("symbol not offered")
                if self._is_full(packet_idx, state):
                    raise ValueError("already decoded")
                if not self.packets[packet_idx]["release"] <= tick < self.packets[packet_idx]["deadline"]:
                    raise ValueError("outside release/deadline")
                if any(not self._is_full(r, state) for r in self.requires[packet_idx]):
                    raise ValueError("prerequisite not decoded")
                updates.append((packet_idx, row["vector"]))
            for packet_idx, vector in updates:
                trans = self.trans_by_dim[self.dimensions[packet_idx]]
                state_list = list(state)
                state_list[packet_idx] = trans[state_list[packet_idx]][vector]
                state = tuple(state_list)
            for packet_idx in range(len(self.packets)):
                if completion[packet_idx] is None and self._is_full(packet_idx, state):
                    completion[packet_idx] = tick + 1
            for c in used_contacts:
                lu[c["station_idx"]] = (c["band"], tick)

        packets_report = []
        for i, packet in enumerate(self.packets):
            packets_report.append({
                "id": packet["id"],
                "rank": self._rank(i, state),
                "completion": completion[i],
            })
        contacts_used = []
        for tick in sorted(by_tick):
            for contact_id in sorted({row["contact"] for row in by_tick[tick]}):
                contacts_used.append({"tick": tick, "contact": contact_id})
        score = self.score_state(state)
        return {
            "score": {
                "priority": score[0],
                "count": score[1],
                "rank": score[2],
            },
            "packets": packets_report,
            "contacts": contacts_used,
            "transmissions": transmissions,
        }


class _UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra != rb:
            self.parent[rb] = ra


def _split_components(request):
    """Split packets into independent groups.

    Groups are coupled through prerequisites, contacts that serve several
    packets, or contacts that share a station/craft/group while their active
    intervals overlap.  Independent groups are solved separately and their
    additive scores are summed.
    """
    packets = request["packets"]
    contacts = request["contacts"]
    pidx = {p["id"]: i for i, p in enumerate(packets)}
    uf = _UnionFind(len(packets))

    for i, packet in enumerate(packets):
        for req in packet["requires"]:
            uf.union(i, pidx[req])

    for contact in contacts:
        served = [pidx[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in pidx]
        for i in served[1:]:
            uf.union(served[0], i)

    for i, c1 in enumerate(contacts):
        served1 = {pidx[sym["packet"]] for sym in c1["symbols"] if sym["packet"] in pidx}
        if not served1:
            continue
        for c2 in contacts[:i]:
            served2 = {pidx[sym["packet"]] for sym in c2["symbols"] if sym["packet"] in pidx}
            if not served2:
                continue
            overlap = c1["start"] < c2["end"] and c2["start"] < c1["end"]
            if c1["station"] == c2["station"]:
                connected = True
            elif c1["craft"] == c2["craft"] and overlap:
                connected = True
            elif c1["group"] == c2["group"] and overlap:
                connected = True
            else:
                connected = False
            if connected:
                uf.union(next(iter(served1)), next(iter(served2)))

    groups = {}
    for i in range(len(packets)):
        groups.setdefault(uf.find(i), []).append(i)
    return [sorted(indices) for indices in groups.values()]


def _component_is_single_machine(packets, contacts):
    """Return true for one-contact-per-packet, one-global-resource cases.

    When every contact shares one craft and every station is unique, all used
    contacts conflict at every tick but there is no station cooldown coupling.
    The component can then be solved by allocating whole ticks to packets.
    """
    if len(packets) < 2:
        return False
    if any(p["requires"] for p in packets):
        return False
    if len({c["craft"] for c in contacts}) != 1:
        return False
    if len({c["station"] for c in contacts}) != len(contacts):
        return False

    packet_index = {p["id"]: i for i, p in enumerate(packets)}
    owner = [None] * len(packets)
    for contact in contacts:
        served = {packet_index[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in packet_index}
        if len(served) != 1:
            return False
        packet_idx = next(iter(served))
        if owner[packet_idx] is not None:
            return False
        owner[packet_idx] = contact
    return all(item is not None for item in owner)


def _packet_count_outcomes(packet, contact):
    """Best per-packet score for exactly ``k`` used ticks, without early full."""
    dimension = packet["dimension"]
    bases, rank_table, trans = _build_subspaces(dimension)
    full_state = next(i for i, r in enumerate(rank_table) if r == dimension)
    offers = tuple(sym["vector"] for sym in contact["symbols"]
                   if 1 <= sym["vector"] < (1 << dimension))

    first_tick = max(contact["start"], packet["release"])
    last_tick = min(contact["end"], packet["deadline"])
    max_k = max(0, last_tick - first_tick)

    batch_options = []
    rate = contact["rate"]
    for size in range(1, rate + 1):
        batch_options.extend(combinations_with_replacement(offers, size))

    reachable = [set() for _ in range(max_k + 1)]
    parent = [dict() for _ in range(max_k + 1)]
    reachable[0].add(0)
    for k in range(1, max_k + 1):
        for state in reachable[k - 1]:
            if state == full_state:
                continue
            for batch in batch_options:
                new_state = state
                for vector in batch:
                    new_state = trans[new_state][vector]
                if new_state not in reachable[k]:
                    reachable[k].add(new_state)
                    parent[k][new_state] = (state, batch)

    outcomes = []
    best_states = []
    for k in range(max_k + 1):
        best = None
        best_state = None
        for state in reachable[k]:
            rank = rank_table[state]
            if state == full_state:
                outcome = (packet["priority"], 1, dimension)
            else:
                outcome = (0, 0, rank)
            if best is None or outcome > best:
                best = outcome
                best_state = state
        outcomes.append(best)
        best_states.append(best_state)
    return first_tick, last_tick, max_k, full_state, rank_table, outcomes, best_states, parent


def _schedule_ticks(counts, intervals, horizon):
    """Assign ``counts[i]`` distinct ticks inside interval i, or return None."""
    n = len(counts)
    order = sorted(range(n), key=lambda i: (counts[i], intervals[i][1] - intervals[i][0]))
    used = [False] * horizon
    ticks = [None] * n

    def backtrack(idx):
        if idx == n:
            return True
        packet_idx = order[idx]
        need = counts[packet_idx]
        if need == 0:
            return backtrack(idx + 1)
        start, end = intervals[packet_idx]
        available = [t for t in range(start, end) if not used[t]]
        if len(available) < need:
            return False
        for chosen in combinations(available, need):
            for t in chosen:
                used[t] = True
            ticks[packet_idx] = chosen
            if backtrack(idx + 1):
                return True
            for t in chosen:
                used[t] = False
            ticks[packet_idx] = None
        return False

    if not backtrack(0):
        return None
    return ticks


def _solve_single_machine(packets, contacts, switch_cooldown):
    """Exact solver for one-contact-per-packet single-global-resource cases."""
    del switch_cooldown  # unique stations make cooldown irrelevant
    packet_index = {p["id"]: i for i, p in enumerate(packets)}
    contact_for = [None] * len(packets)
    for contact in contacts:
        served = {packet_index[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in packet_index}
        contact_for[next(iter(served))] = contact

    horizon = max(c["end"] for c in contacts)
    intervals = []
    max_ks = []
    outcomes = []
    best_states = []
    parents = []
    rank_tables = []
    full_states = []
    for packet, contact in zip(packets, contact_for):
        first, last, max_k, full_state, rank_table, out, best_state, parent =             _packet_count_outcomes(packet, contact)
        intervals.append((first, last))
        max_ks.append(max_k)
        outcomes.append(out)
        best_states.append(best_state)
        parents.append(parent)
        rank_tables.append(rank_table)
        full_states.append(full_state)

    best_key = None
    best_counts = None
    best_ticks = None
    counts = []

    def rec(packet_idx):
        nonlocal best_key, best_counts, best_ticks
        if packet_idx == len(packets):
            ticks = _schedule_ticks(tuple(counts), intervals, horizon)
            if ticks is None:
                return
            key = (0, 0, 0)
            for i, k in enumerate(counts):
                outcome = outcomes[i][k]
                key = (key[0] + outcome[0], key[1] + outcome[1],
                       key[2] + outcome[2])
            if best_key is None or key > best_key:
                best_key = key
                best_counts = tuple(counts)
                best_ticks = ticks
            return
        for k in range(max_ks[packet_idx] + 1):
            counts.append(k)
            rec(packet_idx + 1)
            counts.pop()

    rec(0)

    transmissions = []
    contacts_used = []
    packets_report = []
    score = {"priority": 0, "count": 0, "rank": 0}
    for packet_idx, packet in enumerate(packets):
        k = best_counts[packet_idx]
        contact = contact_for[packet_idx]
        final_state = best_states[packet_idx][k]
        rank = rank_tables[packet_idx][final_state]
        completion = None
        if final_state == full_states[packet_idx]:
            completion = best_ticks[packet_idx][-1] + 1 if k else None
        packets_report.append({
            "id": packet["id"],
            "rank": rank,
            "completion": completion,
        })
        score["rank"] += rank
        if completion is not None:
            score["priority"] += packet["priority"]
            score["count"] += 1

        if k == 0:
            continue
        sequence = []
        state = final_state
        for used in range(k, 0, -1):
            previous, batch = parents[packet_idx][used][state]
            sequence.append(batch)
            state = previous
        sequence.reverse()
        for tick, batch in zip(best_ticks[packet_idx], sequence):
            for vector in batch:
                transmissions.append({
                    "tick": tick,
                    "contact": contact["id"],
                    "packet": packet["id"],
                    "vector": vector,
                })
            contacts_used.append({"tick": tick, "contact": contact["id"]})

    contacts_used.sort(key=lambda row: (row["tick"], row["contact"]))
    transmissions.sort(key=lambda row: (row["tick"], row["contact"], row["packet"], row["vector"]))
    return {
        "score": score,
        "packets": packets_report,
        "contacts": contacts_used,
        "transmissions": transmissions,
    }


def _optimize_component(request, indices):
    packets = [request["packets"][i] for i in indices]
    packet_ids = {p["id"] for p in packets}
    contacts = []
    for contact in request["contacts"]:
        symbols = [sym for sym in contact["symbols"] if sym["packet"] in packet_ids]
        if symbols:
            contacts.append(dict(contact, symbols=symbols))
    if not contacts:
        packets_report = [{"id": p["id"], "rank": 0, "completion": None}
                          for p in packets]
        return {
            "score": {"priority": 0, "count": 0, "rank": 0},
            "packets": packets_report,
            "contacts": [],
            "transmissions": [],
        }
    if _component_is_single_machine(packets, contacts):
        return _solve_single_machine(packets, contacts, request["switch_cooldown"])
    subrequest = {
        "switch_cooldown": request["switch_cooldown"],
        "packets": packets,
        "contacts": contacts,
    }
    opt = Optimizer(subrequest)
    transmissions = opt.run()
    return opt.replay(transmissions)


def optimize(request):
    """Return a full report for ``request``."""
    components = _split_components(request)
    if len(components) == 1:
        return _optimize_component(request, components[0])

    reports = [_optimize_component(request, indices) for indices in components]
    score = {"priority": 0, "count": 0, "rank": 0}
    packets = []
    contacts = []
    transmissions = []
    for report in reports:
        for key in score:
            score[key] += report["score"][key]
        packets.extend(report["packets"])
        contacts.extend(report["contacts"])
        transmissions.extend(report["transmissions"])
    packet_order = {p["id"]: i for i, p in enumerate(request["packets"])}
    packets.sort(key=lambda row: packet_order[row["id"]])
    return {
        "score": score,
        "packets": packets,
        "contacts": contacts,
        "transmissions": transmissions,
    }

