                if self._is_full(packet_idx, state):
                    raise ValueError("already decoded")
                if not self.packets[packet_idx]["release"] <= tick < self.packets[packet_idx]["deadline"]:
                    raise ValueError("outside release/deadline")
                if any(not self._is_full(r, state) for r in self.requires[packet_idx]):
                    raise ValueError("prerequisite not decoded")
                updates.append((packet_idx, row["vector"]))
            for packet_idx, vector in updates:
                trans = self.trans_by_dim[self.dimensions[packet_idx]]
                state_list = list(state)
                state_list[packet_idx] = trans[state_list[packet_idx]][vector]
                state = tuple(state_list)
            for packet_idx in range(len(self.packets)):
                if completion[packet_idx] is None and self._is_full(packet_idx, state):
                    completion[packet_idx] = tick + 1
            for c in used_contacts:
                lu[c["station_idx"]] = (c["band"], tick)

        packets_report = []
        for i, packet in enumerate(self.packets):
            packets_report.append({
                "id": packet["id"],
                "rank": self._rank(i, state),
                "completion": completion[i],
            })
        contacts_used = []
        for tick in sorted(by_tick):
            for contact_id in sorted({row["contact"] for row in by_tick[tick]}):
                contacts_used.append({"tick": tick, "contact": contact_id})
        score = self.score_state(state)
        return {
            "score": {
                "priority": score[0],
                "count": score[1],
                "rank": score[2],
            },
            "packets": packets_report,
