def _split_components(request):
    """Split packets into independent groups.

    Groups are coupled through prerequisites, contacts that serve several
    packets, or contacts that share a station/craft/group while their active
    intervals overlap.  Independent groups are solved separately and their
    additive scores are summed.
    """
    packets = request["packets"]
    contacts = request["contacts"]
    pidx = {p["id"]: i for i, p in enumerate(packets)}
    uf = _UnionFind(len(packets))

    for i, packet in enumerate(packets):
        for req in packet["requires"]:
            uf.union(i, pidx[req])

    for contact in contacts:
        served = [pidx[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in pidx]
        for i in served[1:]:
            uf.union(served[0], i)

    for i, c1 in enumerate(contacts):
        served1 = {pidx[sym["packet"]] for sym in c1["symbols"] if sym["packet"] in pidx}
        if not served1:
            continue
        for c2 in contacts[:i]:
            served2 = {pidx[sym["packet"]] for sym in c2["symbols"] if sym["packet"] in pidx}
            if not served2:
                continue
            overlap = c1["start"] < c2["end"] and c2["start"] < c1["end"]
            if c1["station"] == c2["station"]:
                connected = True
            elif c1["craft"] == c2["craft"] and overlap:
                connected = True
            elif c1["group"] == c2["group"] and overlap:
                connected = True
            else:
                connected = False
            if connected:
                uf.union(next(iter(served1)), next(iter(served2)))

    groups = {}
    for i in range(len(packets)):
        groups.setdefault(uf.find(i), []).append(i)
    return [sorted(indices) for indices in groups.values()]


def _component_is_single_machine(packets, contacts):
    """Return true for one-contact-per-packet, one-global-resource cases.

    When every contact shares one craft and every station is unique, all used
    contacts conflict at every tick but there is no station cooldown coupling.
    The component can then be solved by allocating whole ticks to packets.
    """
    if len(packets) < 2:
        return False
    if any(p["requires"] for p in packets):
        return False
    if len({c["craft"] for c in contacts}) != 1:
        return False
    if len({c["station"] for c in contacts}) != len(contacts):
        return False

    packet_index = {p["id"]: i for i, p in enumerate(packets)}
    owner = [None] * len(packets)
    for contact in contacts:
        served = {packet_index[sym["packet"]] for sym in contact["symbols"]
                  if sym["packet"] in packet_index}
        if len(served) != 1:
            return False
        packet_idx = next(iter(served))
        if owner[packet_idx] is not None:
            return False
        owner[packet_idx] = contact
    return all(item is not None for item in owner)


def _packet_count_outcomes(packet, contact):
    """Best per-packet score for exactly ``k`` used ticks, without early full."""
    dimension = packet["dimension"]
    bases, rank_table, trans = _build_subspaces(dimension)
    full_state = next(i for i, r in enumerate(rank_table) if r == dimension)
    offers = tuple(sym["vector"] for sym in contact["symbols"]
                   if 1 <= sym["vector"] < (1 << dimension))

    first_tick = max(contact["start"], packet["release"])
    last_tick = min(contact["end"], packet["deadline"])
    max_k = max(0, last_tick - first_tick)

    batch_options = []
    rate = contact["rate"]
    for size in range(1, rate + 1):
        batch_options.extend(combinations_with_replacement(offers, size))

    reachable = [set() for _ in range(max_k + 1)]
    parent = [dict() for _ in range(max_k + 1)]
    reachable[0].add(0)
    for k in range(1, max_k + 1):
        for state in reachable[k - 1]:
            if state == full_state:
                continue
            for batch in batch_options:
                new_state = state
                for vector in batch:
                    new_state = trans[new_state][vector]
                if new_state not in reachable[k]:
                    reachable[k].add(new_state)
                    parent[k][new_state] = (state, batch)

    outcomes = []
    best_states = []
    for k in range(max_k + 1):
        best = None
        best_state = None
        for state in reachable[k]:
            rank = rank_table[state]
            if state == full_state:
                outcome = (packet["priority"], 1, dimension)
            else:
                outcome = (0, 0, rank)
            if best is None or outcome > best:
                best = outcome
                best_state = state
        outcomes.append(best)
        best_states.append(best_state)
    return first_tick, last_tick, max_k, full_state, rank_table, outcomes, best_states, parent


