"""Exact finite-horizon optimizer for the coded downlink problem.

The state for one packet is its current GF(2) span, represented as the ID of a
canonical subspace.  Ticks are advanced one at a time; at each tick the locally
legal contact choices are enumerated and deduplicated by the resulting
(packet-spans, station-history) state so redundant transmissions do not cause an
explosion.
"""

from itertools import combinations, combinations_with_replacement

from engines.analysis.coding_basis import add_symbols


def _build_subspaces(dimension):
    nonzeros = list(range(1, 1 << dimension))
    seen = set()
    bases = []
    # Every subspace has a basis of at most ``dimension`` nonzero vectors.
    for size in range(0, dimension + 1):
        for comb in combinations(nonzeros, size):
            basis = add_symbols(dimension, (), comb)
            if basis not in seen:
                seen.add(basis)
                bases.append(basis)
    bases.sort(key=lambda b: (len(b), b))
    id_map = {basis: i for i, basis in enumerate(bases)}
    rank = [len(basis) for basis in bases]
    trans = []
    size = 1 << dimension
    for basis in bases:
        row = [0] * size
        for vector in nonzeros:
            new_basis = add_symbols(dimension, basis, (vector,))
            row[vector] = id_map[new_basis]
        trans.append(tuple(row))
    return tuple(bases), rank, trans


class Optimizer:
    def __init__(self, request):
        self.switch_cooldown = request["switch_cooldown"]
        self.packets = request["packets"]
        self.contacts = request["contacts"]

        self.packet_ids = [p["id"] for p in self.packets]
        self.packet_index = {p["id"]: i for i, p in enumerate(self.packets)}
        self.dimensions = [p["dimension"] for p in self.packets]
        self.priorities = [p["priority"] for p in self.packets]
        self.releases = [p["release"] for p in self.packets]
        self.deadlines = [p["deadline"] for p in self.packets]
        self.requires = [
            tuple(self.packet_index[r] for r in p["requires"])
            for p in self.packets
        ]

        # Per-dimension subspace tables.
        self.rank_by_dim = {}
        self.trans_by_dim = {}
        for dimension in sorted({d for d in self.dimensions}):
            _, ranks, trans = _build_subspaces(dimension)
            self.rank_by_dim[dimension] = ranks
            self.trans_by_dim[dimension] = trans

        self.full_state = {
            dimension: next(
                i for i, r in enumerate(self.rank_by_dim[dimension]) if r == dimension
            )
            for dimension in self.rank_by_dim
        }

        # Normalise contact fields for fast lookups.
        self.stations = sorted({c["station"] for c in self.contacts})
        self.station_index = {s: i for i, s in enumerate(self.stations)}
        self.contact_list = []
        for raw in self.contacts:
            c = dict(raw)
            c["station_idx"] = self.station_index[c["station"]]
            c["symbols"] = self._valid_symbols(c)
            self.contact_list.append(c)

        self.horizon = max(c["end"] for c in self.contact_list)
        self.initial_state = tuple(0 for _ in self.packets)
        self.initial_lu = tuple(None for _ in self.stations)

        self.memo = {}
        self.action_memo = {}

    # ------------------------------------------------------------------
    def _valid_symbols(self, contact):
        rows = []
        for symbol in contact["symbols"]:
            packet_idx = self.packet_index.get(symbol["packet"])
            if packet_idx is None:
                continue
            packet = self.packets[packet_idx]
            vector = symbol["vector"]
            if (packet["craft"], packet["band"]) != (contact["craft"], contact["band"]):
                continue
            if vector < 1 or vector >= (1 << packet["dimension"]):
                continue
            rows.append((packet_idx, vector))
        return tuple(rows)

    def _is_full(self, packet_idx, state):
        return state[packet_idx] == self.full_state[self.dimensions[packet_idx]]

    def _rank(self, packet_idx, state):
        dim = self.dimensions[packet_idx]
        return self.rank_by_dim[dim][state[packet_idx]]

    def score_state(self, state):
        priority = 0
        count = 0
        rank = 0
        for i, _ in enumerate(self.packets):
            r = self._rank(i, state)
            rank += r
            if self._is_full(i, state):
                priority += self.priorities[i]
                count += 1
        return (priority, count, rank)

    def _cooldown_ok(self, contact, tick, lu):
        last = lu[contact["station_idx"]]
        if last is None:
            return True
        last_band, last_tick = last
        if last_band == contact["band"]:
            return True
        return tick - last_tick > self.switch_cooldown

    def _eligible_at(self, tick, state):
        eligible = set()
        for i, packet in enumerate(self.packets):
            if self._is_full(i, state):
                continue
            if not packet["release"] <= tick < packet["deadline"]:
                continue
            if all(self._is_full(r, state) for r in self.requires[i]):
                eligible.add(i)
        return eligible

    def _contact_choices(self, contact, tick, state, eligible):
        """Return distinct resulting-state choices for one active contact."""
        offers = [row for row in contact["symbols"] if row[0] in eligible]
        if not offers:
