def _valid_symbols(self, contact):
    rows = []
    for symbol in contact["symbols"]:
        packet_idx = self.packet_index.get(symbol["packet"])
        if packet_idx is None:
            continue
        packet = self.packets[packet_idx]
        vector = symbol["vector"]
        if (packet["craft"], packet["band"]) != (contact["craft"], contact["band"]):
            continue
        if vector < 1 or vector >= (1 << packet["dimension"]):
            continue
        rows.append((packet_idx, vector))
    return tuple(rows)

def _is_full(self, packet_idx, state):
    return state[packet_idx] == self.full_state[self.dimensions[packet_idx]]

def _rank(self, packet_idx, state):
    dim = self.dimensions[packet_idx]
    return self.rank_by_dim[dim][state[packet_idx]]

def score_state(self, state):
    priority = 0
    count = 0
    rank = 0
    for i, _ in enumerate(self.packets):
        r = self._rank(i, state)
        rank += r
        if self._is_full(i, state):
            priority += self.priorities[i]
            count += 1
    return (priority, count, rank)

def _cooldown_ok(self, contact, tick, lu):
    last = lu[contact["station_idx"]]
    if last is None:
        return True
    last_band, last_tick = last
    if last_band == contact["band"]:
        return True
    return tick - last_tick > self.switch_cooldown

def _eligible_at(self, tick, state):
    eligible = set()
    for i, packet in enumerate(self.packets):
        if self._is_full(i, state):
            continue
        if not packet["release"] <= tick < packet["deadline"]:
            continue
        if all(self._is_full(r, state) for r in self.requires[i]):
            eligible.add(i)
    return eligible

