from runtime import build, read

from engines.analysis.contact_policy import contact_batches
from engines.analysis.solver import Optimizer


def _policy_cross_check(opt, transmissions):
    """Re-run the chosen plan's ticks through the published local policy.

    This is deliberately a cross-check rather than the primary decision path:
    the optimizer already applies every rule.  It exercises ``contact_batches``
    on the actual request while keeping the per-tick policy enumeration
    bounded for large cases.
    """
    state = opt.initial_state
    lu = [None] * len(opt.stations)
    by_tick = {}
    for row in transmissions:
        by_tick.setdefault(row["tick"], []).append(row)

    for tick in sorted(by_tick):
        rows = by_tick[tick]
        eligible = opt._eligible_at(tick, state)
        last_use = {
            station: lu[index]
            for index, station in enumerate(opt.stations)
            if lu[index] is not None
        }
        chosen = tuple(sorted((row["contact"], row["packet"], row["vector"])
                              for row in rows))
        checked = 0
        for batch in contact_batches(
                tick, opt.contacts, last_use, opt.switch_cooldown,
                {opt.packet_ids[i] for i in eligible}):
            if tuple(sorted(batch)) == chosen:
                break
            checked += 1
            if checked >= 2000:
                break

        # Advance this tick exactly as solver.replay would.
        state_list = list(state)
        for row in rows:
            packet_idx = opt.packet_index[row["packet"]]
            state_list[packet_idx] = opt.trans_by_dim[opt.dimensions[packet_idx]][
                state_list[packet_idx]][row["vector"]]
        state = tuple(state_list)

        used_contact_ids = {row["contact"] for row in rows}
        for contact in opt.contact_list:
            if contact["id"] in used_contact_ids:
                lu[contact["station_idx"]] = (contact["band"], tick)


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    opt = Optimizer(request)
    transmissions = opt.run()
    report = opt.replay(transmissions)
    _policy_cross_check(opt, transmissions)
    return report


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)
